using System.Collections.Generic;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;

namespace Demo.Cuentas
{
    public static class CuentasEndpoints
    {
        private static readonly Dictionary<int, decimal> Saldos =
            new Dictionary<int, decimal> { { 1, 1500.00m } };

        private static readonly Dictionary<int, string[]> Movs =
            new Dictionary<int, string[]> { { 1, new[] { "mov-1", "mov-2" } } };

        public static void Register(IEndpointRouteBuilder endpoints)
        {
            endpoints.MapGet("/api/cuentas/{id}/saldo", (int id) => GetSaldo(id));
            endpoints.MapGet("/api/cuentas/{id}/movimientos", (int id) => GetMovimientos(id));
        }

        private static IResult GetSaldo(int id)
            => Saldos.TryGetValue(id, out var saldo) ? Results.Ok(saldo) : Results.NotFound();

        private static IResult GetMovimientos(int id)
            => Movs.TryGetValue(id, out var movs) ? Results.Ok(movs) : Results.NotFound();
    }
}

