interface MovimientosDrawerProps {
  movimientos: string[];
  open: boolean;
}

export function MovimientosDrawer({ movimientos, open }: MovimientosDrawerProps) {
  if (!open) return null;
  return (
    <aside className="fixed right-0 top-0 h-full w-80 border-l bg-white p-4">
      <h2 className="text-lg text-gray-900">Movimientos</h2>
      <ul>
        {movimientos.map((m) => (
          <li key={m} className="text-gray-900">
            {m}
          </li>
        ))}
      </ul>
    </aside>
  );
}

